def graph_laplacian(n, edges):
    L = [[0]*n for _ in range(n)]
    for u, v in edges:
        L[u][v] = -1; L[v][u] = -1
        L[u][u] += 1; L[v][v] += 1
    return L

# Path graph P_4
L = graph_laplacian(4, [(0,1),(1,2),(2,3)])
for i, row in enumerate(L):
    print(f'Row {i}: {row}, sum = {sum(row)}')

def laplacian_at(L, f, v):
    return sum(L[v][w]*f[w] for w in range(len(f)))

def is_harmonic_on(L, S, f):
    return all(laplacian_at(L, f, v) == 0 for v in S)

L = [[1,-1,0,0],[-1,2,-1,0],[0,-1,2,-1],[0,0,-1,1]]
S = {1, 2}
print('Linear [0,1,2,3]:', is_harmonic_on(L, S, [0,1,2,3]))
print('Constant [5,5,5,5]:', is_harmonic_on(L, S, [5,5,5,5]))
print('Sum [5,6,7,8]:', is_harmonic_on(L, S, [5,6,7,8]))

def has_negative_cycle(n, edges):
    dist = [0.0]*n; pred = [-1]*n
    for _ in range(n-1):
        for u,v,w in edges:
            if dist[u]+w < dist[v]:
                dist[v] = dist[u]+w; pred[v] = u
    for u,v,w in edges:
        if dist[u]+w < dist[v]: return True
    return False

# Feasible system
print('Feasible:', not has_negative_cycle(3, [(1,0,3),(2,1,-1),(2,0,4)]))
# Infeasible (negative cycle: 1+(-3)+1 = -1 < 0)
print('Infeasible:', has_negative_cycle(3, [(0,1,1),(1,2,-3),(2,0,1)]))

