def graph_laplacian(n: int, edges: list[tuple[int,int]]) -> list[list[int]]:
    L = [[0]*n for _ in range(n)]
    for u, v in edges:
        L[u][v] = -1; L[v][u] = -1
        L[u][u] += 1; L[v][v] += 1
    return L

def fire_vertex(L: list[list[int]], config: list[int], v: int) -> list[int]:
    new = config[:]
    for w in range(len(config)):
        new[w] += L[w][v]
    return new

def minplus_matmul(A: list[list[float]], B: list[list[float]]) -> list[list[float]]:
    n = len(A)
    C = [[float('inf')]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                val = A[i][k] + B[k][j]
                if val < C[i][j]:
                    C[i][j] = val
    return C

def has_negative_cycle(n: int, edges: list[tuple[int,int,float]]) -> bool:
    dist = [0.0]*n
    for _ in range(n-1):
        for u,v,w in edges:
            if dist[u]+w < dist[v]:
                dist[v] = dist[u]+w
    for u,v,w in edges:
        if dist[u]+w < dist[v]: return True
    return False
